/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tb_people_after_insert` AFTER INSERT ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs` (
        `table_name`, 
        `table_operation`, 
        `db_user`, 
        `operation_date`, 
        `table_description`, 
        `operation_status`
    ) VALUES (
        'tb_people', 
        'Create', 
        CURRENT_USER(), 
        NOW(), 
        CONCAT('Persona registrada con ID: ', NEW.person_ID, ' (', NEW.given_names, ' ', COALESCE(NEW.family_names, ''), ')'), 
        b'1'
    );
END */;;
