/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tb_people_after_delete` AFTER DELETE ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs` (
        `table_name`, 
        `table_operation`, 
        `db_user`, 
        `operation_date`, 
        `table_description`, 
        `operation_status`
    ) VALUES (
        'tb_people', 
        'Delete', 
        CURRENT_USER(), 
        NOW(), 
        CONCAT('Persona eliminada ID: ', OLD.person_ID, ' (', OLD.given_names, ' ', COALESCE(OLD.family_names, ''), ')'), 
        b'1'
    );
END */;;
