/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_users_after_insert` AFTER INSERT ON `tb_users` FOR EACH ROW BEGIN
    INSERT INTO tb_logs(
        table_name,
        table_operation,
        db_user,
        table_description,
        operation_date,
        operation_status
    )
    VALUES (
        'tb_users',
        'Create',
        USER(),
        CONCAT(
            'Usuario creado. ID=', NEW.ID,
            ', email=', IFNULL(NEW.email, 'N/A'),
            ', nick=', IFNULL(NEW.nick, 'N/A'),
            ', status=', IFNULL(NEW.status, b'1')
        ),
        CURRENT_TIMESTAMP,
        b'1'
    );
END */;;
