CREATE DEFINER=`root`@`localhost` FUNCTION `fn_generar_nombre_completo`(p_genero VARCHAR(25), p_tipo ENUM('NOMBRE','APELLIDO')) RETURNS varchar(150) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
    NO SQL
BEGIN
    DECLARE v_res VARCHAR(150);
    IF p_tipo = 'NOMBRE' THEN
        IF p_genero = 'Hombre' THEN
            SET v_res = ELT(fn_random_int(1, 15),
                'Carlos', 'Juan', 'Luis', 'Miguel', 'José',
                'David', 'Daniel', 'Alejandro', 'Jorge', 'Fernando',
                'Ricardo', 'Eduardo', 'Diego', 'Andrés', 'Mateo');
        ELSEIF p_genero = 'Mujer' THEN
            SET v_res = ELT(fn_random_int(1, 15),
                'María', 'Ana', 'Sofía', 'Valeria', 'Camila',
                'Fernanda', 'Daniela', 'Laura', 'Andrea', 'Paula',
                'Gabriela', 'Natalia', 'Elena', 'Mariana', 'Lucía');
        ELSE
            SET v_res = ELT(fn_random_int(1, 10),
                'Alex', 'Cris', 'Sam', 'Jordan', 'Taylor',
                'Ariel', 'Robin', 'Morgan', 'Casey', 'Jaime');
        END IF;
    ELSE
        SET v_res = CONCAT(
            ELT(fn_random_int(1, 15),
                'García', 'Martínez', 'López', 'González', 'Rodríguez',
                'Hernández', 'Pérez', 'Sánchez', 'Ramírez', 'Cruz',
                'Flores', 'Gómez', 'Morales', 'Vázquez', 'Reyes'),
            ' ',
            ELT(fn_random_int(1, 15),
                'Smith', 'Johnson', 'Williams', 'Brown', 'Jones',
                'Díaz', 'Torres', 'Ruiz', 'Mendoza', 'Castillo',
                'Ortega', 'Silva', 'Rojas', 'Navarro', 'Castro')
        );
    END IF;
    RETURN v_res;
END ;;
