CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_desactivar_carritos_abandonados`(IN p_dias_inactividad INT)
BEGIN
    UPDATE tb_carts
    SET status = b'0',
        last_update = NOW()
    WHERE status = b'1'
      AND COALESCE(last_update, creation_date) < DATE_SUB(NOW(), INTERVAL p_dias_inactividad DAY);
END ;;
