CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_simular_productos_masivo`(
    IN p_cantidad INT,
    IN p_seller_user_id INT UNSIGNED,
    IN p_prefijo_sku VARCHAR(10),
    IN p_prob_activo INT
)
    SQL SECURITY INVOKER
BEGIN
    DECLARE v_contador INT DEFAULT 0;
    DECLARE v_max_prod_id INT UNSIGNED DEFAULT 0;
    DECLARE v_prod_id INT UNSIGNED;
    DECLARE v_total_cats INT DEFAULT 0;
    DECLARE v_offset_cat INT DEFAULT 0;
    DECLARE v_cat_id INT;
    DECLARE v_cat_name VARCHAR(100);
    DECLARE v_sku VARCHAR(50);
    DECLARE v_nombre VARCHAR(250);
    DECLARE v_desc TEXT;
    DECLARE v_precio DECIMAL(10,2);
    DECLARE v_stock INT UNSIGNED;
    DECLARE v_status BIT(1);
    DECLARE v_ownership VARCHAR(20);
    DECLARE v_prob_eff INT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    -- Validaciones básicas
    IF p_cantidad IS NULL OR p_cantidad <= 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Error: p_cantidad debe ser mayor a 0.';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM tb_users WHERE ID = p_seller_user_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Error: p_seller_user_id no existe en tb_users.';
    END IF;

    SELECT COUNT(*) INTO v_total_cats FROM tbc_categories WHERE status = 1;
    IF v_total_cats = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Error: No hay categorías activas en tbc_categories.';
    END IF;

    SET v_prob_eff = COALESCE(p_prob_activo, 90);
    SELECT COALESCE(MAX(ID), 0) INTO v_max_prod_id FROM tb_products;

    START TRANSACTION;

    WHILE v_contador < p_cantidad DO
        SET v_contador    = v_contador + 1;
        SET v_max_prod_id = v_max_prod_id + 1;

        -- Selección cíclica de categoría para garantizar >= 5 productos en TODAS las categorías y subcategorías
        SET v_offset_cat = (v_contador - 1) % v_total_cats;
        SELECT ID, name INTO v_cat_id, v_cat_name
        FROM tbc_categories
        WHERE status = 1
        ORDER BY ID ASC
        LIMIT 1 OFFSET v_offset_cat;

        -- Generar atributos válidos del producto
        SET v_sku    = CONCAT(UPPER(COALESCE(p_prefijo_sku, 'PRD')), '-', LPAD(v_max_prod_id, 6, '0'));
        SET v_nombre = CONCAT(
            ELT(fn_random_int(1, 10), 'Pro', 'Clásico', 'Premium', 'Urbano', 'Esencial', 'Sport', 'Deluxe', 'Básico', 'Edición Especial', 'Moderno'),
            ' ', v_cat_name, ' #', v_max_prod_id
        );
        SET v_desc   = CONCAT('Artículo de categoría ', v_cat_name, ' con SKU ', v_sku, '. Garantía de fábrica y envío estándar.');
        SET v_precio = ROUND(50 + (RAND() * 2450), 2);
        SET v_status = fn_generar_estado_prob(v_prob_eff);

        -- Si está descontinuado (b'0'), stock en 0 o bajo; si está activo, stock entre 5 y 250
        IF v_status = b'0' THEN
            SET v_stock = 0;
        ELSE
            SET v_stock = fn_random_int(5, 250);
        END IF;

        SET v_ownership = ELT(fn_random_int(1, 3), 'Owner', 'Reseller', 'Distributor');

        -- 1. Insertar producto
        INSERT INTO tb_products (SKU, name, description, current_price, current_stock, status)
        VALUES (v_sku, v_nombre, v_desc, v_precio, v_stock, v_status);

        SET v_prod_id = LAST_INSERT_ID();

        -- 2. Vincular con su categoría/subcategoría
        INSERT INTO tbd_products_categories (product_ID, category_ID, status)
        VALUES (v_prod_id, v_cat_id, b'1');

        -- 3. Vincular con su vendedor/proveedor
        INSERT INTO tbd_products_users_providers (user_ID, product_ID, type_ownership, status, avalaible_date)
        VALUES (p_seller_user_id, v_prod_id, v_ownership, b'1', NOW());
    END WHILE;

    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
