/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_simular_usuarios_masivo`(
    IN p_cantidad INT,
    IN p_genero VARCHAR(25),
    IN p_pais CHAR(3),
    IN p_edad_min INT,
    IN p_edad_max INT,
    IN p_prob_activa INT
)
BEGIN
    DECLARE v_contador INT DEFAULT 0;
    DECLARE v_max_id INT DEFAULT 0;
    DECLARE v_user_id INT;
    DECLARE v_genero_actual VARCHAR(25);
    DECLARE v_pais_actual CHAR(2);
    DECLARE v_edad_min_eff INT;
    DECLARE v_edad_max_eff INT;
    DECLARE v_prob_eff INT;
    DECLARE v_nombre VARCHAR(150);
    DECLARE v_apellido VARCHAR(150);
    DECLARE v_nacimiento DATE;
    DECLARE v_status BIT(1);
    DECLARE v_nick VARCHAR(50);
    DECLARE v_email VARCHAR(100);
    DECLARE v_telefono VARCHAR(25);
    DECLARE v_titulo VARCHAR(20);

    -- Manejo de errores SQL con reversión automática
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    -- Validación de parámetro obligatorio
    IF p_cantidad IS NULL OR p_cantidad <= 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Error: El parámetro p_cantidad debe ser mayor a 0.';
    END IF;

    -- Resolución de comodines y valores por defecto
    SET v_edad_min_eff = COALESCE(p_edad_min, 18);
    SET v_edad_max_eff = COALESCE(p_edad_max, 70);
    SET v_prob_eff     = COALESCE(p_prob_activa, 100);

    IF v_edad_min_eff > v_edad_max_eff THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Error: p_edad_min no puede ser mayor que p_edad_max.';
    END IF;

    -- Obtener el último ID para garantizar nick y email únicos
    SELECT COALESCE(MAX(ID), 0) INTO v_max_id FROM tb_users;

    START TRANSACTION;

    WHILE v_contador < p_cantidad DO
        SET v_contador = v_contador + 1;
        SET v_max_id   = v_max_id + 1;

        -- 1. Resolver Género (comodín si es NULL, '' o 'ALL')
        IF p_genero IS NULL OR p_genero = '' OR UPPER(p_genero) = 'ALL' THEN
            SET v_genero_actual = ELT(fn_random_int(1, 3), 'Hombre', 'Mujer', 'Prefiero no decirlo');
        ELSE
            SET v_genero_actual = p_genero;
        END IF;

        -- 2. Resolver País (comodín si es NULL, '' o 'ALL')
        IF p_pais IS NULL OR p_pais = '' OR UPPER(p_pais) = 'ALL' THEN
            SET v_pais_actual = fn_generar_pais();
        ELSE
            SET v_pais_actual = LEFT(UPPER(p_pais), 2);
        END IF;

        -- 3. Generar atributos personales y de cuenta
        SET v_nombre     = fn_generar_nombre_completo(v_genero_actual, 'NOMBRE');
        SET v_apellido   = fn_generar_nombre_completo(v_genero_actual, 'APELLIDO');
        SET v_nacimiento = fn_generar_fecha_nacimiento(v_edad_min_eff, v_edad_max_eff);
        SET v_status     = fn_generar_estado_prob(v_prob_eff);
        SET v_nick       = CONCAT(LOWER(LEFT(v_nombre, 3)), LOWER(LEFT(REPLACE(v_apellido, ' ', ''), 4)), '_', v_max_id);
        SET v_email      = CONCAT(v_nick, '@ecommerce-sim.com');
        SET v_telefono   = CONCAT('+', fn_random_int(1, 59), '-', fn_random_int(100, 999), '-', fn_random_int(1000000, 9999999));
        SET v_titulo     = IF(v_genero_actual = 'Hombre', 'Sr.', IF(v_genero_actual = 'Mujer', 'Sra.', 'Mx.'));

        -- 4. Insertar en tb_users
        INSERT INTO tb_users (email, nick, password, creation_date, status)
        VALUES (v_email, v_nick, SHA2(CONCAT('Pass_', v_max_id), 256), NOW(), v_status);

        SET v_user_id = LAST_INSERT_ID();

        -- 5. Insertar en tb_people vinculado por user_ID
        INSERT INTO tb_people (
            user_ID, courtesy_title, given_names, family_names,
            birth_date, gender, country_code, phone, status, creation_date
        )
        VALUES (
            v_user_id, v_titulo, v_nombre, v_apellido,
            v_nacimiento, v_genero_actual, v_pais_actual, v_telefono, v_status, NOW()
        );
    END WHILE;

    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
